demo.program:
// 42 scope demo (simulated model)
console.log('42: attitude + orbit, N spacecraft');
console.log('dynamics workhorse');

// Quaternion demo (simulated model)
var th=90*Math.PI/180;
var q=[Math.cos(th/2),0,Math.sin(th/2),0];
var n=Math.sqrt(q[0]*q[0]+q[1]*q[1]+q[2]*q[2]+q[3]*q[3]);
console.log('q=['+q.map(function(v){return v.toFixed(3);})+'] |q|='+n.toFixed(3));

// Orbit demo (simulated model)
var mu=398600, r=6778;
var v=Math.sqrt(mu/r), T=2*Math.PI*Math.sqrt(r*r*r/mu);
console.log('LEO: v='+v.toFixed(2)+'km/s T='+(T/60).toFixed(1)+'min');

// Wheel demo (simulated model)
var Hw=10, Ib=500;
var dth=Hw/Ib;
console.log('wheel dH=10 Nms -> body slew '+(dth*57.3).toFixed(2)+'deg/s equivalent');
console.log('momentum traded');

// Thruster demo (simulated model)
var F=22, arm=1.2, I=500;
var alpha=F*arm/I;
console.log('22N @1.2m: alpha='+alpha.toFixed(4)+' rad/s^2');
console.log('coarse actuation modeled');

// Sensor demo (simulated model)
var truth=45.0, noise=0.05;
var meas=truth+(0.03-0.05);
console.log('truth '+truth+' measured '+meas.toFixed(2)+'deg');
console.log('noise modeled');

// GPS demo (simulated model)
var sats=8, dop=1.2, sig=5;
console.log(sats+' sats DOP '+dop+': pos err ~'+(dop*sig).toFixed(1)+'m');
console.log('navigation modeled');

// Formation demo (simulated model)
var n=4;
for(var i=0;i<n;i++){console.log('MMS-'+(i+1)+' stationed');}
console.log(n+' spacecraft, one sim');

// Flex demo (simulated model)
var modes=[0.8,2.1,4.5];
for(var i=0;i<modes.length;i++){console.log('mode '+(i+1)+': '+modes[i]+'Hz');}
console.log('flexibility in the loop');

// Disturbance demo (simulated model)
var gg=1e-5, aero=2e-6, srp=1e-6;
console.log('worst disturbance: '+Math.max(gg,aero,srp)+' Nm');
console.log('torques budgeted');

// Safe mode demo (simulated model)
console.log('FAULT -> safe mode: sun-point, 5W positive');
console.log('survival attitude held');

// MC demo (simulated model)
var n=100, worst=0;
for(var i=0;i<n;i++){var e=Math.abs(Math.sin(i*7)*0.5);if(e>worst)worst=e;}
console.log(n+' runs: worst pointing err '+worst.toFixed(2)+'deg');

// MMS demo (simulated model)
console.log('tetrahedron: 10km baselines held');
console.log('formation sim validated');

// Truth/filter demo (simulated model)
var truth=100, belief=98.5;
console.log('truth '+truth+' belief '+belief+' gap '+(truth-belief).toFixed(1));
console.log('navigation proven in the gap');

// Workflow demo (simulated model)
var w=['spacecraft','orbit','GNC','monte carlo','margins'];
for(var i=0;i<w.length;i++){console.log((i+1)+'. '+w[i]);}
console.log('42 workflow complete');
